from typing import Any, Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class PinMessageResponseSchema(BaseRapiResponseSchema): ...


class DraftSetResponseSchema(BaseRapiResponseSchema): ...


class SetDlgStateResponseSchema(BaseRapiResponseSchema): ...


class DelMsgBatchResultsSchema(pydantic.BaseModel):
    silent: bool


class DelMsgBatchResponseSchema(BaseRapiResponseSchema):
    # results: DelMsgBatchResultsSchema    # noqa: ERA001
    ...


class ParentTopic(pydantic.BaseModel):
    chatId: str
    messageId: int
    type: str


class Yours(pydantic.BaseModel):
    lastRead: Optional[int]
    lastReadMention: Optional[int]
    lastDelivered: Optional[int]


class Theirs(pydantic.BaseModel):
    lastDelivered: int
    lastRead: int


class MchatState(pydantic.BaseModel):
    membersVersion: str
    infoVersion: str


class Person(pydantic.BaseModel):
    sn: str
    firstName: Optional[str]
    lastName: Optional[str]
    friendly: Optional[str]
    nick: Optional[str]


class GetHistoryResultsSchema(pydantic.BaseModel):
    parentTopic: Optional[ParentTopic]
    repliesCount: Optional[int]
    lastMsgId: int
    patchVersion: str
    unreadCnt: Optional[int]
    unreadMentionMeCount: Optional[int]
    yours: Optional[Yours]
    theirs: Optional[Theirs]
    lastReadMention: Optional[int]
    delUpto: Optional[int]
    mchatState: Optional[MchatState]
    noRecentsUpdate: Optional[bool]
    messages: list
    olderMsgId: Optional[int]
    newerMsgId: Optional[int]
    pinned: Optional[list]
    patch: Optional[list]
    draft: Optional[dict[str, Any]]
    persons: list[Person]


class GetHistoryResponseSchema(BaseRapiResponseSchema):
    results: GetHistoryResultsSchema
